UPDATE whale_permissions SET is_deleted = 1, deleted_at = NOW(6), deleted_by = #{deletedBy} WHERE name IN
#{name}
AND (tenant_id = #{tenantId} OR tenant_id IS NULL) AND is_deleted = 0

UPDATE whale_permission_grants SET is_deleted = 1, deleted_at = NOW(6), deleted_by = #{deletedBy} WHERE permission_name IN
#{pn}
AND is_deleted = 0
